-- insert-granada-centers.sql
-- Inserta los 60 centros de educacion infantil de primer ciclo (0-3 anos)
-- del termino municipal de Granada capital investigados y humanizados en este sprint.
-- Fuente primaria: "Centros de primer ciclo de educacion infantil en Andalucia, con
-- alumnado matriculado" (Junta de Andalucia, Consejeria de Desarrollo Educativo y
-- Formacion Profesional, portal de datos abiertos), filtrado por D_MUNICIPIO='Granada'
-- y cod_municipio='18087'. Complementado con la web oficial de la Fundacion Publica
-- Local GranadaEduca (las 4 escuelas infantiles municipales: Arlequin, Belen, Duende,
-- Luna) y con webs oficiales propias de un subconjunto de centros privados para
-- confirmar servicios concretos. Ver docs/data-sources-granada.md y
-- data/enrichment/granada-centers.json.
--
-- Ambito: unicamente el termino municipal de Granada capital (D_MUNICIPIO='Granada'
-- y cod_municipio='18087' en la fuente oficial). Se excluyen explicitamente los
-- otros 31 municipios de la provincia de Granada (Armilla, Maracena, Las Gabias,
-- Peligros, Churriana de la Vega, Huetor Vega, Cenes de la Vega, Ogijares, Albolote,
-- Atarfe, Pinos Puente, Santa Fe, etc.) aunque aparecieran en la misma fuente
-- provincial.
--
-- Ownership: se ha usado 'publico' para los 14 centros de titularidad publica
-- genuina: 10 de la red autonomica de la Junta de Andalucia (Almanjayar, Cristo de
-- la Yedra, Portal de Belen, El Principe, Santo Domingo, Virgen del Carmen, Virgen
-- de Loreto, Virgen Inmaculada, Los Mondragones, Juan Latino) y 4 de la red
-- municipal del Ayuntamiento de Granada gestionada por la Fundacion Publica Local
-- GranadaEduca (Arlequin, Belen, Duende, Luna; catalogadas como "Centro de Convenio"
-- en el registro autonomico, verificadas como titularidad municipal genuina en
-- fundaciongranadaeduca.org). Los 46 centros privados (33 adheridos al Programa de
-- Ayuda a las Familias de la Junta de Andalucia + 13 no adheridos, segun el propio
-- registro oficial) llevan ownership='privado', nunca 'concertado': Andalucia no
-- tiene concierto educativo formal para el primer ciclo de infantil (0-3 anos),
-- siguiendo el mismo criterio validado tras la correccion post-auditoria de Sevilla
-- y aplicado desde el origen en Malaga. Nota: varios centros privados de este
-- dataset (La Asuncion, San Isidoro, Monaita/Mulhacen, Nazaret) tienen concierto
-- educativo en etapas posteriores (Primaria/Secundaria), pero NO en el primer ciclo
-- 0-3 anos, que es el unico alcance de este proyecto; se ha respetado la
-- clasificacion oficial especifica de 0-3 anos (Privado, no adherido) en los cuatro
-- casos. Ver docs/granada-quality-report.md, seccion 1.
--
-- Todos los centros entran con status='draft' (no visibles publicamente por RLS hasta
-- cambiarlos a 'published' manualmente tras auditoria, igual que en Madrid, Barcelona,
-- Valencia, Zaragoza, Murcia, Sevilla, Palma, Malaga y Alicante).
-- No toca ningun centro de Madrid, Barcelona, Valencia, Zaragoza, Murcia, Sevilla,
-- Palma, Malaga ni Alicante.
-- No borra ni modifica filas existentes (upsert por slug: si un slug ya existe se
-- actualiza, no se duplica).
-- Generado: 2026-07-12. Revisar antes de ejecutar.
-- Sin DELETE / DROP / TRUNCATE.

BEGIN;

-- Aseguramos que la ciudad "granada" existe antes de insertar sus centros.
INSERT INTO cities (slug, name, province, region)
VALUES ('granada', 'Granada', 'Granada', 'Andalucía')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO centers (
  slug, name, type, ownership, street, postal_code, city_slug, city_name, neighborhood, district, neighborhood_barrio, latitude, longitude, phone, email, website, age_min_months, age_max_months, schedule, services, short_description, long_description, images, faqs, is_claimed, is_verified, social_links, pedagogical_approach, source_url, source_urls_secondary, verified_at, verification_status, confidence_level, data_conflicts, status
)
VALUES
